def llenar_entregas(apps, schema_editor):
    from django.utils import timezone
    Evaluacion = apps.get_model('rh', 'Evaluacion')
    EvaluacionDet = apps.get_model('rh', 'EvaluacionDet')
    Empleado = apps.get_model('rh', 'Empleado')
    Competencia = apps.get_model('rh', 'Competencia')
    Asignada = apps.get_model('rh', 'EmpleadoCompetenciaAsignada')
    Entrega = apps.get_model('rh', 'EvaluacionEntrega')

    generales = set(Competencia.objects.filter(id_clasificacion__tipo='G').values_list('id_competencia', flat=True))
    asignadas = {}
    for emp, comp in Asignada.objects.values_list('id_empleado_id', 'id_competencia_id'):
        asignadas.setdefault(emp, set()).add(comp)
    contestadas = {}
    for ev, emp, tipo, comp, cal in EvaluacionDet.objects.values_list(
            'id_evaluacion_id', 'id_empleado_id', 'tipo', 'id_competencia_id', 'calificacion'):
        llave = (ev, emp, tipo)
        contestadas.setdefault(llave, set())
        if cal:
            contestadas[llave].add(comp)
    empleados = {e.pk: e for e in Empleado.objects.filter(pk__in={k[1] for k in contestadas})}
    ahora = timezone.now()
    nuevas = []
    for (ev, emp, tipo), hechas in contestadas.items():
        e = empleados.get(emp)
        if e is None or tipo not in ('E', 'J'):
            continue
        requeridas = set() if (tipo == 'E' and not e.se_evalua) else (generales | asignadas.get(emp, set()))
        completa = bool(requeridas) and requeridas <= hechas
        nuevas.append(Entrega(id_evaluacion_id=ev, id_empleado_id=emp, tipo=tipo, empresa_id=e.empresa_id,
                              contestadas=len(requeridas & hechas), total=len(requeridas),
                              completa=completa, fecha_completa=ahora if completa else None))
    Entrega.objects.bulk_create(nuevas)


